    def test_transition_rechecks_ownership_after_lock_entry(self):
        # A deterministic lock-entry seam models invalidation after the first
        # check and before acquiring the transition lock; no thread is started.
        class InvalidateAtEnter:
            def __init__(self, original, invalidate):
                self.original, self.invalidate = original, invalidate
            def __enter__(self):
                self.original.__enter__()
                self.invalidate()
                return self
            def __exit__(self, *args):
                return self.original.__exit__(*args)
        names = ("bind_worker", "require_resume", "resume_owned", "revoke_local",
                 "quarantine", "complete", "reconcile_live")
        for name in names:
            for invalidation in ("live", "gate"):
                with self.subTest(name=name, invalidation=invalidation):
                    f = Fixture()
                    token = f.start()
                    if name in ("require_resume", "resume_owned", "reconcile_live"):
                        f.service.bind_worker(token, f.worker)
                    if name == "reconcile_live":
                        f.service.revoke_local(token)
                    before, events = f.stream.getvalue(), list(f.events)
                    if invalidation == "live":
                        invalidate = lambda: f.service._live.pop(token.gate, None)
                    else:
                        invalidate = lambda: f.gates._held.__setitem__(P, object())
                    token._lock = InvalidateAtEnter(token._lock, invalidate)
                    actions = {
                        "bind_worker": lambda: f.service.bind_worker(token, f.worker),
                        "require_resume": lambda: f.service.require_resume(token),
                        "resume_owned": lambda: f.service.resume_owned(token, lambda worker: self.fail("stale resume")),
                        "revoke_local": lambda: f.service.revoke_local(token),
                        "quarantine": lambda: f.service.quarantine(token, "operation_failed"),
                        "complete": lambda: f.service.complete(token, f.finish),
                        "reconcile_live": lambda: f.service.reconcile_live(token),
                    }
                    with self.assertRaisesRegex(ReservationRefused, "live_reservation_required|gate_owner_required"):
                        actions[name]()
                    self.assertEqual(f.stream.getvalue(), before)
                    self.assertEqual(f.events, events)
                    self.assertEqual(f.live_reconciliation_calls, [])

    def test_roundtrip_valid_history(self):
        raw = encode_next(b"", P, S, None, "INITIALIZED")
        raw += encode_next(raw, P, S, G, "RESERVED")
        raw += encode_next(raw, P, S, G, "WORKER_BOUND", process=[1234, 987654321000])
        rows, head = decode_journal(raw)
        self.assertEqual([row["phase"] for row in rows], ["INITIALIZED", "RESERVED", "WORKER_BOUND"])
        self.assertEqual(rows[-1]["process"], [1234, 987654321000])
        self.assertEqual(len(head), 64)

